questionvariables.text:
/* Select a standard angle (degrees) */
angle_index: rand(5);
angle_list: [0,30,45,60,90];
theta: angle_list[angle_index+1];

/* Exact trigonometric ratios */
cos_theta: cos(theta*%pi/180);
sin_theta: sin(theta*%pi/180);
tan_theta: if theta = 90 then und else sin_theta/cos_theta;

/* Possible student mistakes */
cos_swap: sin_theta;      /* gave sin instead of cos */
sin_swap: cos_theta;      /* gave cos instead of sin */
cos_double: 2*cos_theta;  /* used the 1 : sqrt(3) : 2 or 1 : 1 : sqrt(2) triangle without scaling it so the hypotenuse is 1 */
sin_double: 2*sin_theta;
